#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){string p;cin>>p;vector<string>st;
string cur;
auto flush=[&](){if(cur==".."){if(!st.empty())st.pop_back();}
else if(cur!=""&&cur!=".")st.push_back(cur);cur="";};
for(char c:p){if(c=='/')flush();else cur+=c;}
flush();
string r;
for(auto&x:st)r+="/"+x;
if(r.empty())r="/";
printf("%s\n",r.c_str());return 0;}

